const SplitConfigurationRuleSchema = z
  .strictObject({
    cardRegion: z
      .enum(['international', 'intraEEA', 'intraRegional', 'interRegional', 'domestic', 'ANY'])
      .exactOptional()
      .openapi({
        description:
          'The card region condition that determines whether the [split logic](https://docs.adyen.com/api-explorer/Management/latest/post/merchants/(merchantId)/splitConfigurations#request-rules-splitLogic) applies to the transaction.\n\nPossible values:\n* **domestic**: The card issuer and the store where the transaction is processed are registered in the same country.\n* **international**: The card issuer and the store where the transaction is processed are registered in different countries or regions. Includes all **interRegional** and **intraRegional** transactions.\n* **interRegional**: The card issuer and the store where the transaction is processed are registered in different regions.\n* **intraRegional**: The card issuer and the store where the transaction is processed are registered in different countries, but in the same region.\n* **intraEEA**: The card issuer and the store where the transaction is processed are registered in different countries, but in the European Economic Area (EEA).\n* **ANY**: Applies to all transactions, regardless of the processing and issuing country/region.',
      }),
    cardUsageType: z
      .enum(['commercial', 'consumer', 'ANY'])
      .exactOptional()
      .openapi({
        description:
          'The card usage type condition that determines whether the split logic applies to commercial cards, consumer cards, or all cards.\n\n* **ANY** (default): The split logic applies to all cards, regardless of its usage type.\n* **commercial**: The split logic applies to commercial cards only.\n* **consumer**: The split logic applies to consumer cards only.',
      }),
    currency: z
      .string()
      .openapi({
        description:
          'The currency condition that defines whether the split logic applies.\nIts value must be a three-character [ISO currency code](https://en.wikipedia.org/wiki/ISO_4217).',
      }),
    fundingSource: z
      .enum(['charged', 'credit', 'debit', 'deferred_debit', 'prepaid', 'ANY'])
      .openapi({
        description:
          'The funding source of the payment method.\n\nPossible values:\n* **credit**\n* **debit**\n* **prepaid**\n* **deferred_debit**\n* **charged**\n* **ANY**',
      }),
    paymentMethod: z
      .string()
      .openapi({
        description:
          'The payment method condition that defines whether the split logic applies.\n\nPossible values:\n* [Payment method variant](https://docs.adyen.com/development-resources/paymentmethodvariant): Apply the split logic for a specific payment method.\n* **ANY**: Apply the split logic for all available payment methods.',
      }),
    ruleId: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The unique identifier of the split configuration rule.',
        readOnly: true,
      }),
    shopperInteraction: z
      .enum(['Ecommerce', 'ContAuth', 'Moto', 'POS', 'ANY'])
      .openapi({
        description:
          'The sales channel condition that defines whether the split logic applies.\n\nPossible values:\n* **Ecommerce**: Online transactions where the cardholder is present.\n* **ContAuth**: Card on file and/or subscription transactions, where the cardholder is known to the merchant (returning customer).\n* **Moto**: Mail-order and telephone-order transactions where the customer is in contact with the merchant via email or telephone.\n* **POS**: Point-of-sale transactions where the customer is physically present to make a payment using a secure payment terminal.\n* **ANY**: All sales channels.',
      }),
    splitLogic: SplitConfigurationLogicSchema.openapi({
      description: 'Contains the split logic that is applied if the rule conditions are met.',
    }),
  })
  .openapi({
    required: ['currency', 'fundingSource', 'paymentMethod', 'shopperInteraction', 'splitLogic'],
  })
  .openapi('SplitConfigurationRule')

