const UpdateSplitConfigurationLogicRequestSchema = z
  .strictObject({
    acquiringFees: z
      .enum(['deductFromLiableAccount', 'deductFromOneBalanceAccount'])
      .exactOptional()
      .openapi({
        description:
          'Deducts the acquiring fees (the aggregated amount of interchange and scheme fee) from the specified balance account.\n\nPossible values: **deductFromLiableAccount**, **deductFromOneBalanceAccount**.',
      }),
    additionalCommission: AdditionalCommissionSchema.exactOptional().openapi({
      description:
        "Defines whether to book an additional commission for payments to your user's balance account. The commission amount can be defined as a fixed amount (specified in minor units), a percentage (specified in basis points), or both.",
    }),
    adyenCommission: z
      .enum(['deductFromLiableAccount', 'deductFromOneBalanceAccount'])
      .exactOptional()
      .openapi({
        description:
          'Deducts the transaction fee due to Adyen under [blended rates](https://www.adyen.com/knowledge-hub/guides/payments-training-guide/get-the-best-from-your-card-processing) from the specified balance account.\n\nPossible values: **deductFromLiableAccount**, **deductFromOneBalanceAccount**.',
      }),
    adyenFees: z
      .enum(['deductFromLiableAccount', 'deductFromOneBalanceAccount'])
      .exactOptional()
      .openapi({
        description:
          'Deducts the fees due to Adyen (markup or commission) from the specified balance account.\n\nPossible values: **deductFromLiableAccount**, **deductFromOneBalanceAccount**.',
      }),
    adyenMarkup: z
      .enum(['deductFromLiableAccount', 'deductFromOneBalanceAccount'])
      .exactOptional()
      .openapi({
        description:
          'Deducts the transaction fee due to Adyen under [Interchange ++ pricing](https://www.adyen.com/what-is-interchange) from the specified balance account.\n\nPossible values: **deductFromLiableAccount**, **deductFromOneBalanceAccount**.',
      }),
    chargeback: z
      .enum([
        'deductFromLiableAccount',
        'deductFromOneBalanceAccount',
        'deductAccordingToSplitRatio',
      ])
      .exactOptional()
      .openapi({
        description:
          'Specifies how and from which balance account(s) to deduct the chargeback amount.\n\nPossible values: **deductFromLiableAccount**, **deductFromOneBalanceAccount**, **deductAccordingToSplitRatio**.',
      }),
    chargebackCostAllocation: z
      .enum(['deductFromLiableAccount', 'deductFromOneBalanceAccount'])
      .exactOptional()
      .openapi({
        description:
          'Deducts the chargeback costs from the specified balance account.\n\nPossible values: **deductFromLiableAccount**, **deductFromOneBalanceAccount**',
      }),
    commission: CommissionSchema.openapi({
      description:
        "Defines your platform's commission for the processed payments as a fixed amount (specified in minor units), a percentage (specified in basis points), or both. The commission is booked to your platform's liable balance account.",
    }),
    dcc: SplitDccSchema.exactOptional().openapi({
      description:
        'Defines the logic for booking the markup paid by the customer for Dynamic Currency Conversion (DCC).\n\n> This field is in pilot phase, and not yet available for all platforms.',
    }),
    interchange: z
      .enum(['deductFromLiableAccount', 'deductFromOneBalanceAccount'])
      .exactOptional()
      .openapi({
        description:
          'Deducts the interchange fee from specified balance account.\n\nPossible values: **deductFromLiableAccount**, **deductFromOneBalanceAccount**.',
      }),
    paymentFee: z
      .enum(['deductFromLiableAccount', 'deductFromOneBalanceAccount'])
      .exactOptional()
      .openapi({
        description:
          "Deducts all transaction fees incurred by the payment from the specified balance account. The transaction fees include the acquiring fees (interchange and scheme fee), and the fees due to Adyen (markup or commission). You can book any and all these fees to different balance account by specifying other transaction fee parameters in your split configuration profile:\n\n- [`adyenCommission`](https://docs.adyen.com/api-explorer/Management/latest/post/merchants/(merchantId)/splitConfigurations#request-rules-splitLogic-adyenCommission): The transaction fee due to Adyen under [blended rates](https://www.adyen.com/knowledge-hub/interchange-fees-explained#interchange-vs-blended).\n- [`adyenMarkup`](https://docs.adyen.com/api-explorer/Management/latest/post/merchants/(merchantId)/splitConfigurations#request-rules-splitLogic-adyenMarkup): The transaction fee due to Adyen under [Interchange ++ pricing](https://www.adyen.com/knowledge-hub/interchange-fees-explained#interchange-vs-blended).\n- [`schemeFee`](https://docs.adyen.com/api-explorer/Management/latest/post/merchants/(merchantId)/splitConfigurations#request-rules-splitLogic-schemeFee): The fee paid to the card scheme for using their network.\n- [`interchange`](https://docs.adyen.com/api-explorer/Management/latest/post/merchants/(merchantId)/splitConfigurations#request-rules-splitLogic-interchange): The fee paid to the issuer for each payment transaction made with the card network.\n- [`adyenFees`](https://docs.adyen.com/api-explorer/Management/latest/post/merchants/(merchantId)/splitConfigurations#request-rules-splitLogic-adyenFees): The aggregated amount of Adyen's commission and markup.\n- [`acquiringFees`](https://docs.adyen.com/api-explorer/Management/latest/post/merchants/(merchantId)/splitConfigurations#request-rules-splitLogic-acquiringFees): The aggregated amount of the interchange and scheme fees.\n\nIf you don't include at least one transaction fee type in the `splitLogic` object, Adyen updates the payment request with the `paymentFee` parameter, booking all transaction fees to your platform's liable balance account.\n\nPossible values: **deductFromLiableAccount**, **deductFromOneBalanceAccount**.",
      }),
    refund: z
      .enum([
        'deductFromLiableAccount',
        'deductFromOneBalanceAccount',
        'deductAccordingToSplitRatio',
      ])
      .exactOptional()
      .openapi({
        description:
          'Specifies how and from which balance account(s) to deduct the refund amount.\n\nPossible values: **deductFromLiableAccount**, **deductFromOneBalanceAccount**, **deductAccordingToSplitRatio**',
      }),
    refundCostAllocation: z
      .enum(['deductFromLiableAccount', 'deductFromOneBalanceAccount'])
      .exactOptional()
      .openapi({
        description:
          'Deducts the refund costs from the specified balance account.\n\nPossible values: **deductFromLiableAccount**, **deductFromOneBalanceAccount**',
      }),
    remainder: z
      .enum(['addToLiableAccount', 'addToOneBalanceAccount'])
      .exactOptional()
      .openapi({
        description:
          'Books the amount left over after currency conversion to the specified balance account.\n\nPossible values: **addToLiableAccount**, **addToOneBalanceAccount**.',
      }),
    schemeFee: z
      .enum(['deductFromLiableAccount', 'deductFromOneBalanceAccount'])
      .exactOptional()
      .openapi({
        description:
          'Deducts the scheme fee from the specified balance account.\n\nPossible values: **deductFromLiableAccount**, **deductFromOneBalanceAccount**.',
      }),
    splitLogicId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Unique identifier of the collection of split instructions that are applied when the rule conditions are met.',
        readOnly: true,
      }),
    surcharge: z
      .enum(['addToLiableAccount', 'addToOneBalanceAccount'])
      .exactOptional()
      .openapi({
        description:
          'Books the surcharge amount to the specified balance account.\n\nPossible values: **addToLiableAccount**, **addToOneBalanceAccount**',
      }),
    tip: z
      .enum(['addToLiableAccount', 'addToOneBalanceAccount'])
      .exactOptional()
      .openapi({
        description:
          'Books the tips (gratuity) to the specified balance account.\n\nPossible values: **addToLiableAccount**, **addToOneBalanceAccount**.',
      }),
  })
  .openapi({ required: ['commission'] })
  .openapi('UpdateSplitConfigurationLogicRequest')

