export const getStoresRoute = createRoute({
  method: 'get',
  path: '/stores',
  tags: ['Account - store level'],
  summary: 'Get a list of stores',
  description:
    'Returns a list of stores. The list is grouped into pages as defined by the query parameters.\n\nTo make this request, your API credential must have one of the following [roles](https://docs.adyen.com/development-resources/api-credentials#api-permissions):\n* Management API—Stores read\n* Management API—Stores read and write\n\nIn the live environment, requests to this endpoint are subject to [rate limits](https://docs.adyen.com/point-of-sale/automating-terminal-management#rate-limits-in-the-live-environment).',
  operationId: 'get-stores',
  request: {
    query: z.object({
      pageNumber: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'pageNumber',
            in: 'query',
            description: 'The number of the page to fetch.',
            required: false,
            style: 'form',
            explode: true,
            schema: { type: 'integer', format: 'int32' },
          },
        }),
      pageSize: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'pageSize',
            in: 'query',
            description:
              'The number of items to have on a page, maximum 100. The default is 10 items on a page.',
            required: false,
            style: 'form',
            explode: true,
            schema: { type: 'integer', format: 'int32' },
          },
        }),
      reference: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'reference',
            in: 'query',
            description: 'The reference of the store.',
            required: false,
            style: 'form',
            explode: true,
            schema: { type: 'string' },
          },
        }),
      merchantId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'merchantId',
            in: 'query',
            description: 'The unique identifier of the merchant account.',
            required: false,
            style: 'form',
            explode: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK - the request has succeeded.',
      content: {
        'application/json': {
          schema: ListStoresResponseSchema,
          examples: { success: GetStoresSuccess_200Example },
        },
      },
    },
    400: {
      description: 'Bad Request - a problem reading or understanding the request.',
      content: { 'application/json': { schema: RestServiceErrorSchema } },
    },
    401: {
      description: 'Unauthorized - authentication required.',
      content: { 'application/json': { schema: RestServiceErrorSchema } },
    },
    403: {
      description: 'Forbidden - insufficient permissions to process the request.',
      content: { 'application/json': { schema: RestServiceErrorSchema } },
    },
    422: {
      description: 'Unprocessable Entity - a request validation error.',
      content: { 'application/json': { schema: RestServiceErrorSchema } },
    },
    500: {
      description: 'Internal Server Error - the server could not process the request.',
      content: { 'application/json': { schema: RestServiceErrorSchema } },
    },
  },
  security: [{ BasicAuth: [] }, { ApiKeyAuth: [] }],
})

