export const getMerchantsMerchantIdTerminalThemesRoute = createRoute({
  method: 'get',
  path: '/merchants/{merchantId}/terminalThemes',
  tags: ['Terminal themes - merchant level'],
  summary: 'List terminal themes',
  description:
    'Returns a paginated list of terminal themes for the merchant account specified in the path. The response provides only the metadata of the themes. Assets (images and videos) are not included. To get the URLs for the assets of a specific theme, make a GET request to the `/merchants/{merchantId}/terminalThemes/{id}` endpoint \n\nTo make this request, your API credential must have the following [role](https://docs.adyen.com/development-resources/api-credentials#manage-api-permissions): \n- Management API - Terminal themes read and write',
  operationId: 'get-merchants-merchantId-terminalThemes',
  request: {
    params: z.object({
      merchantId: z
        .string()
        .openapi({
          param: {
            name: 'merchantId',
            in: 'path',
            description: 'The unique identifier of the merchant account.',
            required: true,
            style: 'simple',
            explode: false,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      pageSize: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(100),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            name: 'pageSize',
            in: 'query',
            description:
              'The number of themes to return per page. If not specified, the list has 10 themes per page.',
            required: false,
            style: 'form',
            explode: true,
            schema: { type: 'integer', format: 'int32', default: 10, maximum: 100, minimum: 1 },
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(10000),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            description:
              'The number of the page to fetch. If not specified, the list starts from page 1.',
            required: false,
            style: 'form',
            explode: true,
            schema: { type: 'integer', format: 'int32', default: 1, maximum: 10000, minimum: 1 },
          },
        }),
      search: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'search',
            in: 'query',
            description:
              'A search term to filter themes by name. The match is case-insensitive and returns any theme with a name that contains the search term.',
            required: false,
            style: 'form',
            explode: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: ListThemesResponseSchema,
          examples: {
            'list-terminal-themes-200': {
              summary: 'Themes listed successfully',
              description: 'list-terminal-themes-200',
              value: {
                data: [
                  { id: 'THEM_001ABC', name: 'BrandDark', mode: 'dark' },
                  { id: 'THEM_002DEF', name: 'BrandLight', mode: 'light' },
                ],
                hasNextPage: false,
              },
            },
          },
        },
      },
    },
    400: { description: 'Bad Request', content: {} },
    401: { description: 'Unauthorized', content: {} },
    403: { description: 'Forbidden', content: {} },
    404: { description: 'Not Found', content: {} },
    422: { description: 'Unprocessable Entity', content: {} },
    500: { description: 'Internal Server Error', content: {} },
  },
  security: [{ BasicAuth: [] }, { ApiKeyAuth: [] }],
})

